// called with the lock held and returns with it released.
func (s *llmSched) runSteps(batch []*llmUnit) {
	// A conversation that hung up while queued is not run.
	live := batch[:0]
	for _, u := range batch {
		if err := u.job.ctx.Err(); err != nil {
			u.err = err
			s.dropUnit(u)
			close(u.done)
			continue
		}
		live = append(live, u)
	}
	batch = live
	if len(batch) == 0 {
		s.mu.Unlock()
		return
	}
	slots := make([]int, len(batch))
	ids := make([]int32, len(batch))
	tracks := make([]bool, len(batch))
	for i, u := range batch {
		slots[i], ids[i] = u.job.slot, u.ids[0]
		tracks[i] = s.specs != nil && s.slots[u.job.slot].track
	}
	s.inflight = batch
	s.batches++
	s.batchRows += len(batch)
	s.mu.Unlock()

	var logits []float32
	t0 := time.Now()
	err := s.dev.Do(func(*vk.Device) error {
		if s.g.Speculating() {
			if err := s.g.Speculate(false); err != nil {
				return err
			}
		}
		var err error
		if logits, err = s.g.DecodeRows(slots, ids); err != nil {
			return err
		}
		// Each row a slot's draft did not see: owed to it (P20f).
		for i := range batch {
			if tracks[i] {
				s.hrow = s.g.ResidualRow(i, s.hrow)
				s.specs[slots[i]].Owe(ids[i], s.hrow)
			}
		}
		return nil
	})
	took := time.Since(t0)

	s.mu.Lock()
	s.inflight = nil
	vocab := 0
	if err == nil {
		vocab = len(logits) / len(batch)
	}
	for i, u := range batch {
		sl := &s.slots[u.job.slot]
		if err != nil {
			// Which rows' states moved is not something this can say.
			sl.held, sl.ckpt, sl.ckptRes, sl.track = nil, nil, nil, false
		} else {
			sl.held = append(sl.held, u.ids[0])
			u.logits = logits[i*vocab : (i+1)*vocab]
			u.job.progress.steps++
		}
		// Each row had the whole pass's latency, and a share of its cost.
		u.busy += took
		u.job.served += took / time.Duration(len(batch))
		u.err = err
		u.ids = nil
		s.dropUnit(u)
		close(u.done)
	}
	s.lastStep = time.Now()
	s.mu.Unlock()
}

// pick is the scheduling policy: the next unit to run, or nil to wait. See
// the file comment for the three rules.
func (s *llmSched) pick() *llmUnit {
	interactive := s.towers > 0
	for i := range s.slots {
		if j := s.slots[i].job; j != nil && j.class == classInteractive {
			interactive = true
		}
	}
	var best *llmUnit
	for _, u := range s.pending {
		if interactive && u.job.class == classBackground {
			continue
		}
		if best == nil || u.job.served < best.job.served ||
			(u.job.served == best.job.served && u.job.arrival < best.job.arrival) {
			best = u
		}
	}
	if best != nil || !interactive {
		return best
	}
	// Rule 1: an interactive job holds the device between its own units.
	// Only when every interactive slot-holder is gone does background run.
	return nil
}

// towerBegin says a request of this class is about to run its images through
// the tower, and returns the call that says it has finished. Only the
// interactive class is counted: a background request's tower is interleaved
// with background units like any other background work.
func (s *llmSched) towerBegin(class llmClass) func() {
	if class != classInteractive {
		return func() {}
	}
	s.mu.Lock()
	s.towers++
	s.mu.Unlock()
	return func() {
		s.mu.Lock()
		s.towers--
		s.wake.Broadcast()
		s.mu.Unlock()
	}
}

func (s *llmSched) dropUnit(u *llmUnit) {
	for i, p := range s.pending {
		if p == u {
			s.pending = append(s.pending[:i], s.pending[i+1:]...)
			return
		}
	}
}

// specFor is the slot's speculator, or nil without a draft head.
func (s *llmSched) specFor(slot int) *llm.Speculator {
	if s.specs == nil {
		return nil
	}
	return s.specs[slot]
}

// speculates is whether a picked decode unit runs as a speculative round
// (P20f): it asked to, its slot's draft is caught up, the round's rows fit
// the cache and the request's budget, and no other conversation of its class
// is decoding — if one is, the two batch as plain rows instead (C5).
func (s *llmSched) speculates(u *llmUnit) bool {
	if !u.round || u.room < 2 || s.specs == nil {
		return false
	}
	sl := &s.slots[u.job.slot]
	if !sl.track || len(sl.held)+s.specDepth+1 > s.g.NKV() {
		return false
	}
	for i := range s.slots {
		if j := s.slots[i].job; j != nil && j != u.job && j.class == u.job.class && j.stepping {
			return false
		}
	}
	return true
}

// runRound runs a speculative round. It is called with the lock held and
// returns with it released.
func (s *llmSched) runRound(u *llmUnit) {
	j := u.job
	slot, id := j.slot, u.ids[0]
	sl := &s.slots[slot]
	sp := s.specs[slot]
	s.running = u
	s.mu.Unlock()

	var toks []int32
	t0 := time.Now()
	ran := false
	err := j.ctx.Err()
	if err == nil {
		ran = true
		err = s.dev.Do(func(*vk.Device) error {
			if err := s.g.UseSlot(slot); err != nil {
