// arm remembers what a speculative pass is about to overwrite. It runs at the
// top of appendN, before anything has moved.
func (g *Graph) arm(nTok int) error {
	if !g.spec {
		return nil
	}
	if g.specArmed {
		return fmt.Errorf("llm: a speculative pass is already in flight; commit or rewind it first")
	}
	if g.specFirst {
		// The ring write keeps any prefix of a run however it compares with
		// the ring's length (llm_seq_hist.comp, P20h), so only the slots
		// bound the pass.
		// A prefix of each length but the first and the whole needs a slot.
		if nTok > g.specWidth {
			return fmt.Errorf("llm: a keep-prefix pass of %d rows; the graph was staged for %d (GraphOpts.SpecRows)",
				nTok, g.specWidth)
		}
	}
	g.specPast, g.specRows, g.specIds, g.specBlocks = g.past, nTok, len(g.ids), nil
	g.specSpans = len(g.spans)
	if g.attn != nil && g.past > 0 {
		snap, err := g.attn.SnapshotBlocks(g.past, nTok)
		if err != nil {
			return err
		}
		g.specBlocks = snap
	}
	g.specArmed = true
	return nil
}

