type llmClass int

const (
	classInteractive llmClass = iota
	classBackground
)

func (c llmClass) String() string {
	if c == classInteractive {
		return "interactive"
	}
	return "background"
}

// parseClass reads a class name, the way the flag and the header spell it.
func parseClass(s string) (llmClass, bool) {
	switch s {
	case "interactive", "priority":
		return classInteractive, true
	case "background", "flex", "default", "auto":
		return classBackground, true
	}
	return 0, false
}

// llmSlot is one of the graph's sequence slots, as the scheduler sees it.
	if opt.Slots == 1 {
		opt.Reserve = 0
	}
	if opt.Reserve < 0 || opt.Reserve >= opt.Slots {
		return nil, fmt.Errorf("backend: %d of %d slots reserved for interactive requests leaves background none",
			opt.Reserve, opt.Slots)
	}
	class := classBackground
	if opt.Class != "" {
		c, ok := parseClass(opt.Class)
		if !ok {
			return nil, fmt.Errorf("backend: priority class %q; want interactive or background", opt.Class)
// service_tier, then the server's default (CONCURRENCY.md, "Priority").
