	if c, ok := parseClass(strings.ToLower(api.Priority(ctx))); ok {
		return c
	}
	switch strings.ToLower(req.ServiceTier) {
	case "priority":
		return classInteractive
	case "flex":
		return classBackground
	}
	return l.class
}

