package backend

import (
	"context"
	"fmt"
	"os"
	"strings"
	"sync"
	"testing"

	"strix-halo-vulkan/api"
)

// TestLLMSpeculationAgentLoop: exploratory repro for "priming the draft at N;
// its cache holds M" — an agent's turns, sampled without a seed, each turn the
// last one's messages plus the assistant's reply and a tool-ish result.
func TestLLMSpeculationAgentLoop(t *testing.T) {
	if _, err := os.Stat(llmTestDraft); err != nil {
		t.Skipf("no draft head at %s", llmTestDraft)
	}
	l := newTestLLM(t, LLMOptions{Slots: 3, Reserve: 0, Draft: llmTestDraft, PreemptChunk: 64})
	ctx := context.Background()
	var sys strings.Builder
	sys.WriteString("You are an agent. The tools:\n")
	for i := range 40 {
		fmt.Fprintf(&sys, "- tool_%d: does thing %d\n", i, i)
	}
	temp := 0.8
	req := func(msgs []api.Message) *api.CompletionRequest {
		return &api.CompletionRequest{Messages: msgs, MaxTokens: 40, Temperature: &temp}
	}
	text := func(s string) api.MessageContent { return api.MessageContent{{Type: "text", Text: s}} }
	agent := func(name string, mangle bool) error {
		msgs := []api.Message{{Role: "system", Content: text(sys.String())}, {Role: "user", Content: text("Task " + name)}}
		for turn := range 5 {
			out, err := complete(ctx, l, req(msgs))
			if err != nil {
				return fmt.Errorf("%s turn %d: %w", name, turn, err)
			}
			reply := joined(out)
			if mangle && turn%2 == 1 {
				reply = strings.TrimSpace(reply) + " (edited)"
			}
			msgs = append(msgs, api.Message{Role: "assistant", Content: text(reply)},
				api.Message{Role: "user", Content: text(fmt.Sprintf("Result %d of %s: %s", turn, name, strings.Repeat("ok ", 20+turn*7)))})
		}
		return nil
	}
	for _, mangle := range []bool{false, true} {
		t.Run(fmt.Sprintf("alone mangle=%v", mangle), func(t *testing.T) {
			if err := agent("solo", mangle); err != nil {
				t.Error(err)
			}
		})
		t.Run(fmt.Sprintf("concurrent mangle=%v", mangle), func(t *testing.T) {
			var wg sync.WaitGroup
			for i := range 3 {
				wg.Add(1)
				go func() {
					defer wg.Done()
					if err := agent(fmt.Sprintf("c%d", i), mangle); err != nil {
						t.Error(err)
					}
				}()
			}
			wg.Wait()
		})
	}
	t.Logf("%d rounds, %d restores, %d batches", l.sched.rounds, l.sched.restores, l.sched.batches)
}

